{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-openclaw-luna6-high-fresh0/frozen/held-out-reference-3/play/users/u056/system/state/workspace/programs/task-4a7e2d1c.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    outer_h, outer_w = r1 - r0 + 1, c1 - c0 + 1
    depth = 1
    colors = (2, 5, 0, 5)
    while True:
        top, bottom = r0 + depth, r1 - depth
        left, right = c0 + depth, c1 - depth
        h, w = bottom - top + 1, right - left + 1
        if h <= 0 or w <= 0:
            break
        color = colors[(depth - 1) % 4]
        if h <= 2 or w <= 2:
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    out[r][c] = color
            break
        for c in range(left, right + 1):
            out[top][c] = out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = out[r][right] = color
        # In the smallest demonstrated frame, the 3x3 zero core remains empty.
        if h == 3 and w == 3 and outer_h == 9 and outer_w == 9:
            break
        depth += 1
    return out
"
}

